     1→import { ORPCError, os } from "@orpc/server";
     2→
     3→import type { Context } from "./context";
     4→
     5→export const o = os.$context<Context>();
     6→
     7→export const publicProcedure = o;
     8→
     9→// Auth middleware
    10→const requireAuth = o.middleware(async ({ context, next }) => {
    11→	if (!context.session?.user) {
    12→		throw new ORPCError("UNAUTHORIZED");
    13→	}
    14→	return next({
    15→		context: {
    16→			session: context.session,
    17→		},
    18→	});
    19→});
    20→
    21→export const protectedProcedure = publicProcedure.use(requireAuth);
    22→
    23→// Organization + role middleware combined
    24→const requireOrgWithRole = (roles: string[]) =>
    25→	o.middleware(async ({ context, next }) => {
    26→		if (!context.activeOrganization) {
    27→			throw new ORPCError("FORBIDDEN", {
    28→				message: "No active organization selected",
    29→			});
    30→		}
    31→		if (!context.membership) {
    32→			throw new ORPCError("FORBIDDEN", {
    33→				message: "You are not a member of this organization",
    34→			});
    35→		}
    36→		if (roles.length > 0 && !roles.includes(context.membership.role)) {
    37→			throw new ORPCError("FORBIDDEN", {
    38→				message: `This action requires one of the following roles: ${roles.join(", ")}`,
    39→			});
    40→		}
    41→		return next({
    42→			context: {
    43→				session: context.session,
    44→				activeOrganization: context.activeOrganization,
    45→				membership: context.membership,
    46→			},
    47→		});
    48→	});
    49→
    50→// Procedure that requires organization membership (any role)
    51→export const organizationProcedure = protectedProcedure.use(
    52→	requireOrgWithRole([]),
    53→);
    54→
    55→// Admin procedure (owner or admin role)
    56→export const adminProcedure = protectedProcedure.use(
    57→	requireOrgWithRole(["owner", "admin"]),
    58→);
    59→
    60→// Owner procedure (owner role only)
    61→export const ownerProcedure = protectedProcedure.use(
    62→	requireOrgWithRole(["owner"]),
    63→);
