    69→// Check for circular dependencies in jump logic
    70→function checkForCircularDependencies(
    71→	rules: Array<{
    72→		sourceQuestionId: string;
    73→		targetQuestionId: string | null;
    74→		action: string;
    75→	}>,
    76→): boolean {
    77→	// Build a graph of question jumps
    78→	const graph = new Map<string, Set<string>>();
    79→
    80→	for (const rule of rules) {
    81→		if (rule.targetQuestionId && rule.action !== "end_survey") {
    82→			const neighbors = graph.get(rule.sourceQuestionId);
    83→			if (neighbors) {
    84→				neighbors.add(rule.targetQuestionId);
    85→			} else {
    86→				graph.set(rule.sourceQuestionId, new Set([rule.targetQuestionId]));
    87→			}
    88→		}
    89→	}
    90→
    91→	// DFS to detect cycles
    92→	const visited = new Set<string>();
    93→	const recursionStack = new Set<string>();
    94→
    95→	function hasCycle(node: string): boolean {
    96→		visited.add(node);
    97→		recursionStack.add(node);
    98→
    99→		const neighbors = graph.get(node);
   100→		if (neighbors) {
   101→			for (const neighbor of neighbors) {
   102→				if (!visited.has(neighbor)) {
   103→					if (hasCycle(neighbor)) return true;
   104→				} else if (recursionStack.has(neighbor)) {
   105→					return true;
   106→				}
   107→			}
   108→		}
   109→
   110→		recursionStack.delete(node);
   111→		return false;
   112→	}
   113→
   114→	for (const node of graph.keys()) {
   115→		if (!visited.has(node)) {
   116→			if (hasCycle(node)) return true;
   117→		}
   118→	}
   119→
   120→	return false;
   121→}
