   274→	// Validate logic rules for circular dependencies
   275→	validate: adminProcedure
   276→		.input(z.object({ surveyId: z.string() }))
   277→		.handler(async ({ input, context }) => {
   278→			await verifySurveyAccess(input.surveyId, context.activeOrganization.id);
   279→
   280→			const rules = await db
   281→				.select()
   282→				.from(logicRule)
   283→				.where(eq(logicRule.surveyId, input.surveyId));
   284→
   285→			const hasCircularDependency = checkForCircularDependencies(
   286→				rules.map((r) => ({
   287→					sourceQuestionId: r.sourceQuestionId,
   288→					targetQuestionId: r.targetQuestionId,
   289→					action: r.action,
   290→				})),
   291→			);
   292→
   293→			// Check for self-referential rules
   294→			const selfReferential = rules.filter(
   295→				(r) => r.sourceQuestionId === r.targetQuestionId,
   296→			);
   297→
   298→			// Check for conflicting rules (same source, different actions)
   299→			const rulesBySource = new Map<string, typeof rules>();
   300→			for (const rule of rules) {
   301→				const existing = rulesBySource.get(rule.sourceQuestionId) ?? [];
   302→				existing.push(rule);
   303→				rulesBySource.set(rule.sourceQuestionId, existing);
   304→			}
   305→
   306→			const conflictingRules: string[] = [];
   307→			for (const [sourceId, sourceRules] of rulesBySource) {
   308→				if (sourceRules.length > 1) {
   309→					// Check for conflicting actions
   310→					const actions = new Set(sourceRules.map((r) => r.action));
   311→					if (
   312→						actions.has("jump_to") &&
   313→						(actions.has("show") || actions.has("hide"))
   314→					) {
   315→						conflictingRules.push(sourceId);
   316→					}
   317→				}
   318→			}
   319→
   320→			return {
   321→				valid: !hasCircularDependency && selfReferential.length === 0,
   322→				hasCircularDependency,
   323→				selfReferentialRules: selfReferential.map((r) => r.id),
   324→				conflictingRules,
   325→			};
   326→		}),
   327→};
