    17→const apiHandler = new OpenAPIHandler(appRouter, {
    18→	plugins: [
    19→		new OpenAPIReferencePlugin({
    20→			schemaConverters: [new ZodToJsonSchemaConverter()],
    21→		}),
    22→	],
    23→	interceptors: [
    24→		onError((error) => {
    25→			console.error(error);
    26→		}),
    27→	],
    28→});
    29→
    30→async function handleRequest(req: NextRequest) {
    31→	const rpcResult = await rpcHandler.handle(req, {
    32→		prefix: "/api/rpc",
    33→		context: await createContext(req),
    34→	});
    35→	if (rpcResult.response) return rpcResult.response;
    36→
    37→	const apiResult = await apiHandler.handle(req, {
    38→		prefix: "/api/rpc/api-reference",
    39→		context: await createContext(req),
    40→	});
    41→	if (apiResult.response) return apiResult.response;
    42→
    43→	return new Response("Not found", { status: 404 });
    44→}
    45→
    46→export const GET = handleRequest;
