   104→
   105→	// Sync state when initialQuestions changes
   106→	useEffect(() => {
   107→		setQuestions(initialQuestions);
   108→	}, [initialQuestions]);
   109→
   110→	// Reorder mutation
   111→	const reorderMutation = useMutation(
   112→		orpc.question.reorder.mutationOptions({
   113→			onSuccess: () => {
   114→				queryClient.invalidateQueries({ queryKey: ["question"] });
   115→			},
   116→			onError: (error) => {
   117→				toast.error(error.message || "Failed to reorder questions");
   118→			},
   119→		}),
   120→	);
   121→
   122→	// DnD sensors
   123→	const sensors = useSensors(
   124→		useSensor(PointerSensor, {
   125→			activationConstraint: {
   126→				distance: 5,
   127→			},
   128→		}),
   129→		useSensor(KeyboardSensor, {
   130→			coordinateGetter: sortableKeyboardCoordinates,
   131→		}),
   132→	);
   133→
   134→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   135→	const collisionDetection: CollisionDetection = (args) => {
   136→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   137→		if (args.active.data.current?.questionType) {
   138→			const pointerCollisions = pointerWithin(args);
   139→			if (pointerCollisions.length > 0) {
   140→				return pointerCollisions;
   141→			}
   142→		}
   143→		// For canvas reordering, use closestCenter for better sortable behavior
   144→		return closestCenter(args);
   145→	};
   146→
   147→	const handleDragStart = (event: DragStartEvent) => {
   148→		const { active } = event;
   149→		const data = active.data.current;
   150→
   151→		if (data?.questionType) {
   152→			// Dragging from palette
   153→			setActiveDragItem({
   154→				type: "palette",
   155→				questionType: data.questionType as Question["type"],
   156→			});
   157→		} else {
   158→			// Dragging existing question
   159→			setActiveDragItem({
   160→				type: "question",
   161→				id: active.id as string,
   162→			});
   163→		}
   164→	};
   165→
   166→	const handleDragOver = (event: DragOverEvent) => {
   167→		const { over } = event;
   168→		setOverId(over?.id as string | null);
   169→	};
   170→
   171→	const handleDragEnd = (event: DragEndEvent) => {
   172→		const { active, over } = event;
   173→		setOverId(null);
   174→
   175→		if (!over) {
   176→			setActiveDragItem(null);
   177→			return;
   178→		}
