   199→			const optimisticQuestions = [
   200→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   201→				{ ...optimisticQuestion, order: insertIndex },
   202→				...questions
   203→					.slice(insertIndex)
   204→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   205→			];
   206→
   207→			setQuestions(optimisticQuestions);
   208→			setSelectedQuestionId(tempId);
   209→
   210→			// Create question and reorder
   211→			client.question
   212→				.create({
   213→					surveyId: survey.id,
   214→					type: questionType,
   215→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   216→					order: insertIndex,
   217→				})
