   219→					// Replace optimistic question with real one
   220→					setQuestions((currentQuestions) => {
   221→						const updatedQuestions = currentQuestions.map((q) =>
   222→							q.id === tempId ? newQuestion : q,
   223→						);
   224→						return updatedQuestions;
   225→					});
   226→
   227→					setSelectedQuestionId((currentId) =>
   228→						currentId === tempId ? newQuestion.id : currentId,
   229→					);
