					label: "retry",
					onClick: query.invalidate,
				},
			});
		},
	}),
});
```

---

### 6. Middleware Deduplication

**NOT USED.** The current implementation uses **middleware chaining** rather than deduplication:
- Each procedure type (`protectedProcedure`, `organizationProcedure`, etc.) builds on the previous one
- The `requireOrgWithRole` middleware is a **factory function** that creates middleware with specific role requirements
- This is standard oRPC pattern, not the experimental `unstable_use` deduplication feature

---

### 7. Auth Integration

**Auth is integrated at two levels:**

1. **Context Creation** (`context.ts`):
   - Uses Better Auth's `auth.api.getSession()` to get the session from request headers
   - Fetches organization membership data

2. **Middleware** (`index.ts`):
   - `requireAuth` middleware validates session exists
   - Session is then available in procedure handlers via `context.session`

---

### 8. Database Context Handling

**Database is accessed directly in procedures, NOT passed through context:**

```typescript
