     2→
     3→import { createORPCClient } from "@orpc/client";
     4→import { RPCLink } from "@orpc/client/fetch";
     5→import { createTanstackQueryUtils } from "@orpc/tanstack-query";
     6→import { QueryCache, QueryClient } from "@tanstack/react-query";
     7→import { toast } from "sonner";
     8→
     9→export const queryClient = new QueryClient({
    10→	queryCache: new QueryCache({
    11→		onError: (error, query) => {
    12→			toast.error(`Error: ${error.message}`, {
    13→				action: {
    14→					label: "retry",
    15→					onClick: query.invalidate,
    16→				},
    17→			});
    18→		},
    19→	}),
    20→});
    21→
    22→export const link = new RPCLink({
    23→	url: `${typeof window !== "undefined" ? window.location.origin : "http://localhost:3001"}/api/rpc`,
    24→	fetch(url, options) {
    25→		return fetch(url, {
    26→			...options,
    27→			credentials: "include",
    28→		});
    29→	},
    30→	headers: async () => {
    31→		if (typeof window !== "undefined") {
    32→			return {};
    33→		}
    34→
    35→		const { headers } = await import("next/headers");
    36→		return Object.fromEntries(await headers());
    37→	},
    38→});
    39→
    40→export const client: AppRouterClient = createORPCClient(link);
